// Writes the daily recaps ("the road so far") into an SQL migration for the online game's server (table public.day_recaps).
// Run: npx tsx scripts/gen-recaps-sql.ts > supabase/migrations/00NN_day_recaps_data.sql
import { DAY_RECAPS } from '../src/data/dayRecaps';

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const rows = DAY_RECAPS.map((r) => `('dark-moon', 1, ${r.week}, ${r.day}, ${q(r.recap)})`);
console.log(`-- The daily recaps for the online game, generated by scripts/gen-recaps-sql.ts from src/data/dayRecaps.ts.
-- Do not edit by hand.
insert into public.day_recaps (series_id, season_number, week, day, recap) values
${rows.join(',\n')}
on conflict (series_id, season_number, week, day) do update set recap = excluded.recap;`);
